insert into public.catalyst_concepts (id, sort_order, group_name, title, summary, levels, pair_notes) values
('verb_final', 1, 'Word order', 'Verb at the end', 'Where the verb goes. Japanese, Burmese and Marathi put it last; Chinese and English put it before the object.', '{"ja-my":"close","ja-zh":"none","ja-mr":"close","my-zh":"none","my-mr":"close","zh-mr":"none","ja-en":"none","my-en":"none","zh-en":"close","mr-en":"none"}'::jsonb, '{"ja-zh":"Chinese is S-V-O. With no particles, order alone tells you who does what: 狗咬人 ''dog bites man'' vs 人咬狗."}'::jsonb),
('modifier_before_noun', 2, 'Word order', 'Describing clause before the noun', '''The book I bought yesterday''. Here Chinese joins Japanese and Burmese: the whole clause comes before the noun.', '{"ja-my":"close","ja-zh":"close","ja-mr":"partial","my-zh":"close","my-mr":"partial","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"Same order. Burmese needs the linker တဲ့ between clause and noun; Japanese just puts the verb form there.","my-zh":"Burmese တဲ့ and Chinese 的 do the same job in the same place.","ja-mr":"Marathi uses participle forms (-लेला, -णारा) for short clauses. Long ones switch to जो … तो."}'::jsonb),
('topic_wa', 3, 'Particles', 'Topic marker は', 'は says ''as for X…''. Nothing else matches it exactly, and this is where false matches start.', '{"ja-my":"partial","ja-zh":"none","ja-mr":"partial","my-zh":"none","my-mr":"partial","zh-mr":"none","ja-en":"partial","my-en":"partial","zh-en":"none","mr-en":"partial"}'::jsonb, '{"ja-zh":"Chinese puts the topic first but has no particle for it. Don''t map は onto 是 or 呢.","ja-my":"Burmese ကတော့ is contrastive ''as for'', like は used for contrast. Plain は usually becomes က or nothing."}'::jsonb),
('subject_ga', 4, 'Particles', 'Subject marker が', 'が marks the subject, especially new information and after question words.', '{"ja-my":"partial","ja-zh":"none","ja-mr":"partial","my-zh":"none","my-mr":"partial","zh-mr":"none","ja-en":"none","my-en":"none","zh-en":"close","mr-en":"none"}'::jsonb, '{"ja-my":"Burmese က marks the subject, often with a ''this one, not others'' feel. It is also the word for ''from''.","ja-mr":"Marathi ने is not a subject marker: it marks the doer only with past transitive verbs."}'::jsonb),
('object_o', 5, 'Particles', 'Object marker を', 'を marks the direct object. Burmese and Marathi mark objects only some of the time, in the same way.', '{"ja-my":"partial","ja-zh":"none","ja-mr":"partial","my-zh":"none","my-mr":"close","zh-mr":"none","ja-en":"none","my-en":"none","zh-en":"close","mr-en":"none"}'::jsonb, '{"ja-my":"を is on every object. Burmese ကို is mostly used for people and specific things; ''drink water'' has none.","my-mr":"Close match: ကို and ला both mark people and definite objects, and both are left off for plain things."}'::jsonb),
('place_de_ni', 6, 'Particles', 'Place: で (action) vs に (existence)', 'Japanese splits ''at a place'' in two. Burmese, Chinese and Marathi use one word for both.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"partial","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"One Burmese particle, two Japanese ones: မှာ = で and に. Going the other way, you must choose.","my-mr":"Both use one ending for ''at / in'': မှာ and -त / मध्ये."}'::jsonb),
('direction_ni_e', 7, 'Particles', 'Going to / giving to: に・へ', 'Goal of movement and the person you give to. Burmese and Marathi reuse their object marker for this.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"partial","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"Burmese ကို covers を (object), に and へ (goal, receiver). Don''t expect a separate ''to'' word.","my-mr":"Exact pair: ကို and ला both mean ''to (a place / a person)'' and also mark people as objects."}'::jsonb),
('also_mo', 8, 'Particles', 'Also: も', '''Me too''. Japanese, Burmese and Marathi attach it to the noun; Chinese puts it before the verb.', '{"ja-my":"close","ja-zh":"partial","ja-mr":"close","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"close","mr-en":"partial"}'::jsonb, '{"ja-zh":"も follows the noun; 也 is an adverb before the verb. ''Both A and B'' in Chinese uses 都."}'::jsonb),
('from_until', 9, 'Particles', 'From … until: から・まで', 'Start and end points, in time or space.', '{"ja-my":"close","ja-zh":"partial","ja-mr":"close","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"close","mr-en":"partial"}'::jsonb, '{"ja-zh":"Chinese 从 … 到 go before the nouns, like English prepositions.","ja-my":"Burmese က alone can mean ''from'', but it is also the subject marker; ကနေ makes ''from'' clear."}'::jsonb),
('possessive_no', 10, 'Particles', 'Possession: の', '''My book'', ''the teacher''s car''.', '{"ja-my":"close","ja-zh":"close","ja-mr":"partial","my-zh":"close","my-mr":"partial","zh-mr":"partial","ja-en":"close","my-en":"close","zh-en":"close","mr-en":"partial"}'::jsonb, '{"ja-mr":"Marathi चा / ची / चे changes with the gender of the thing owned; の never changes.","ja-zh":"Close, but Chinese drops 的 for family and close ties: 我妈妈, not usually 我的妈妈."}'::jsonb),
('with_to', 11, 'Particles', 'And / with: と', 'Japanese と means both ''and'' (between nouns) and ''with''. Burmese and Chinese do the same; Marathi and English split it.', '{"ja-my":"close","ja-zh":"close","ja-mr":"partial","my-zh":"close","my-mr":"partial","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"close"}'::jsonb, '{"ja-zh":"和 / 跟 cover both meanings, but ''with someone'' goes before the verb, often with 一起."}'::jsonb),
('yes_no_ka', 12, 'Questions and endings', 'Yes/no question: か', 'Add a particle at the end. All four Asian languages do this; English changes the word order instead.', '{"ja-my":"close","ja-zh":"close","ja-mr":"close","my-zh":"close","my-mr":"close","zh-mr":"close","ja-en":"none","my-en":"none","zh-en":"none","mr-en":"none"}'::jsonb, '{"ja-my":"Close, but Burmese လား is only for yes/no. Questions with ''what, where'' need လဲ (see next concept)."}'::jsonb),
('wh_question', 13, 'Questions and endings', 'Question words: 何・どこ', 'The question word stays where the answer would go. What happens at the end differs.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"partial","my-zh":"partial","my-mr":"partial","zh-mr":"close","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"Japanese uses か for both kinds of question. Burmese has two endings: လား (yes/no) and လဲ (with a question word).","ja-zh":"Never add 吗 to a 什么 question; with 吗 it means ''something''."}'::jsonb),
('tag_ne', 14, 'Questions and endings', '''…, right?'': ね', 'A small word at the end that asks the listener to agree.', '{"ja-my":"close","ja-zh":"partial","ja-mr":"close","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"ね ≈ နော်. Japanese よ (''I''m telling you'') has no single Burmese word.","ja-mr":"ね ≈ ना, at the end of the sentence."}'::jsonb),
('past', 15, 'Tense and aspect', 'Past: た・ました', 'Japanese and Marathi have a real past tense. Burmese marks it lightly, and Chinese 了 is not a past tense.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"close","my-zh":"partial","my-mr":"partial","zh-mr":"partial","ja-en":"close","my-en":"partial","zh-en":"partial","mr-en":"close"}'::jsonb, '{"ja-zh":"False match: 了 means ''completed'', not ''past''. 他昨天很忙 is past with no 了, and 了 can appear in future plans.","ja-my":"Burmese တယ် covers past and present; ခဲ့ adds ''past'' only when needed.","ja-mr":"Both are true past tenses; Marathi also agrees with gender (and, for transitive verbs, with the object)."}'::jsonb),
('progressive', 16, 'Tense and aspect', 'Ongoing action / state: ている', 'ている means both ''is doing'' and ''is in a state''. The others split these two.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"partial","my-zh":"close","my-mr":"partial","zh-mr":"partial","ja-en":"partial","my-en":"close","zh-en":"close","mr-en":"close"}'::jsonb, '{"ja-my":"ている splits in two: နေ (in progress) and ထား (state left after an action).","my-zh":"Neat pair: နေ ≈ 在 / 正在 (in progress), ထား ≈ 着 (state)."}'::jsonb),
('future', 17, 'Tense and aspect', 'Future / plans', 'Japanese and Chinese have no future tense; Burmese and Marathi do.', '{"ja-my":"partial","ja-zh":"close","ja-mr":"partial","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"close","zh-en":"partial","mr-en":"close"}'::jsonb, '{"ja-my":"Japanese uses the ordinary non-past form for the future. Burmese changes the ending: တယ် → မယ်.","ja-zh":"Both just add a time word (明日 / 明天). Plans: つもり ≈ 打算."}'::jsonb),
('experience', 18, 'Tense and aspect', 'Have done before: たことがある', '''I have climbed Fuji.'' Japanese, Burmese and Chinese each have one fixed form; Marathi has none.', '{"ja-my":"close","ja-zh":"close","ja-mr":"none","my-zh":"close","my-mr":"none","zh-mr":"none","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"close"}'::jsonb, '{"my-zh":"ဖူး and 过 sit in the same place, right after the verb.","ja-mr":"No dedicated form in Marathi; use the perfect tense, often with कधी (''ever'')."}'::jsonb),
('want_tai', 19, 'Mood', 'Want to: たい', 'Japanese and Burmese add an ending to the verb; Chinese puts a word before it.', '{"ja-my":"close","ja-zh":"partial","ja-mr":"partial","my-zh":"partial","my-mr":"partial","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"close","mr-en":"partial"}'::jsonb, '{"ja-my":"Same slot: verb + たい, verb + ချင်.","ja-mr":"Marathi says ''to me it is to-go'': मला जायचं आहे. The person wanting takes ला."}'::jsonb),
('ability', 20, 'Mood', 'Can: できる・potential form', 'Japanese has one ''can''. Burmese, Chinese and Marathi split ''know how to'' from ''be able to''.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"partial","my-zh":"close","my-mr":"close","zh-mr":"close","ja-en":"close","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"Japanese uses one potential form. Burmese makes you choose: တတ် (learned skill) or နိုင် (possible).","my-zh":"တတ် ≈ 会 (learned skill), နိုင် ≈ 能 (able). Chinese adds 可以 for ''allowed''.","my-mr":"တတ် ≈ येणे (मला पोहता येतं), နိုင် ≈ शकणे."}'::jsonb),
('because', 21, 'Mood', 'Because: から・ので', 'Reason first, then the result, with the ''because'' word at the end of the reason.', '{"ja-my":"close","ja-zh":"partial","ja-mr":"close","my-zh":"partial","my-mr":"close","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"close","mr-en":"partial"}'::jsonb, '{"ja-zh":"Chinese puts 因为 at the start of the reason and 所以 at the start of the result.","ja-my":"Same place: reason + から, reason + လို့."}'::jsonb),
('politeness', 22, 'Politeness and negation', 'Polite endings: です・ます', 'Japanese changes the verb ending for the listener. The others show respect in other ways.', '{"ja-my":"partial","ja-zh":"none","ja-mr":"partial","my-zh":"partial","my-mr":"partial","zh-mr":"partial","ja-en":"none","my-en":"partial","zh-en":"close","mr-en":"partial"}'::jsonb, '{"ja-zh":"Chinese verbs have no polite form. Politeness is in words: 您 (polite ''you''), 请 (''please'').","ja-my":"Burmese ပါ makes a sentence polite but is one small word, not a full set of endings. သည် is written style, not politeness.","ja-mr":"Marathi shows respect with the plural ''you'' (तुम्ही / आपण) and its verb form."}'::jsonb),
('negation', 23, 'Politeness and negation', 'Not: ない・ません', 'Where ''not'' goes: after the verb, before it, or around it.', '{"ja-my":"partial","ja-zh":"partial","ja-mr":"close","my-zh":"partial","my-mr":"partial","zh-mr":"partial","ja-en":"partial","my-en":"partial","zh-en":"partial","mr-en":"partial"}'::jsonb, '{"ja-my":"Japanese adds an ending; Burmese wraps the verb: မ + verb + ဘူး.","ja-zh":"Chinese puts 不 or 没 before the verb, and picks one by meaning: 没 = didn''t / haven''t.","ja-mr":"Both put ''not'' after the verb: 食べない, खात नाही."}'::jsonb),
('counters', 24, 'Counting', 'Counters: 本・枚・匹', 'A counting word chosen by the thing''s shape or kind. Burmese is the closest match, even in word order.', '{"ja-my":"close","ja-zh":"partial","ja-mr":"none","my-zh":"partial","my-mr":"none","zh-mr":"none","ja-en":"none","my-en":"none","zh-en":"none","mr-en":"close"}'::jsonb, '{"ja-my":"Same idea and same order: noun + number + counter (ペン三本 / ခဲတံ သုံးချောင်း). Long, flat, animal counters line up too.","ja-zh":"Chinese puts number + counter before the noun: 三支笔.","ja-mr":"Marathi just says the number; only people get a counter (जण)."}'::jsonb)
insert into public.catalyst_entries (id, concept_id, language_code, form, note, has_equivalent, checked) values
('verb_final:ja', 'verb_final', 'ja', 'S – O – V', 'The verb (or adjective, or です) comes last. The rest can move around because particles mark each role.', true, false),
('verb_final:my', 'verb_final', 'my', 'S – O – V', 'Same as Japanese: verb last, followed by its ending (တယ်, မယ်…). Order before the verb is fairly free.', true, false),
('verb_final:zh', 'verb_final', 'zh', 'S – V – O', 'Verb before the object, like English. No case particles, so you cannot move words freely.', true, false),
('verb_final:mr', 'verb_final', 'mr', 'S – O – V', 'Verb last, as in Japanese and Burmese. Unlike them, the verb agrees with the subject''s gender and number.', true, false),
('verb_final:en', 'verb_final', 'en', 'S – V – O', 'Verb before the object. Order carries the meaning.', true, false),
('modifier_before_noun:ja', 'modifier_before_noun', 'ja', 'verb (plain form) + noun', 'No linking word. The plain verb form sits directly in front of the noun.', true, false),
('modifier_before_noun:my', 'modifier_before_noun', 'my', 'verb + တဲ့ + noun', 'The clause ends with တဲ့ (written style: သော), then the noun.', true, false),
('modifier_before_noun:zh', 'modifier_before_noun', 'zh', 'clause + 的 + noun', 'The clause ends with 的, then the noun: the same order as Japanese and Burmese, unlike the rest of Chinese.', true, false),
('modifier_before_noun:mr', 'modifier_before_noun', 'mr', 'participle (-लेला / -णारा) + noun', 'The verb becomes an adjective-like participle that agrees with the noun.', true, false),
('modifier_before_noun:en', 'modifier_before_noun', 'en', 'noun + who / that + clause', 'The clause comes after the noun, with a relative word.', true, false),
('topic_wa:ja', 'topic_wa', 'ja', 'は (read わ)', 'Marks what the sentence is about, which is often not the subject. Also shows contrast.', true, false),
('topic_wa:my', 'topic_wa', 'my', 'ကတော့ / ဟာ / (nothing)', 'No exact equivalent. ကတော့ = ''as for'' with contrast; ဟာ marks a topic in careful speech; often nothing at all.', true, false),
('topic_wa:zh', 'topic_wa', 'zh', '— (topic goes first)', 'No topic particle. You put the topic at the start of the sentence and say the rest about it.', false, false),
('topic_wa:mr', 'topic_wa', 'mr', 'तर (contrast) / (nothing)', 'तर after a word gives ''as for…'', with contrast. Plain topics have no marker.', true, false),
('topic_wa:en', 'topic_wa', 'en', 'as for … / word order, stress', 'Only a phrase (''as for'') or stress.', true, false),
('subject_ga:ja', 'subject_ga', 'ja', 'が', 'New or focused subject; always after question words (誰が, not 誰は).', true, false),
('subject_ga:my', 'subject_ga', 'my', 'က', 'Marks the subject when it matters who does it. Often left out.', true, false),
('subject_ga:zh', 'subject_ga', 'zh', '— (position before the verb)', 'No subject particle. Position does it, and for weather the ''subject'' even comes after the verb.', false, false),
('subject_ga:mr', 'subject_ga', 'mr', 'ने (past transitive only)', 'ने marks the doer only when the verb is past and takes an object. Otherwise there is no marker.', true, false),
('subject_ga:en', 'subject_ga', 'en', '— (position before the verb)', 'No marker; the subject comes before the verb.', false, false),
('object_o:ja', 'object_o', 'ja', 'を (read お)', 'On every direct object.', true, false),
('object_o:my', 'object_o', 'my', 'ကို (people, specific things)', 'Used for people and ''this / that'' things. Plain objects take nothing.', true, false),
('object_o:zh', 'object_o', 'zh', '— (after the verb); 把 for a moved object', 'No object particle. 把 moves a specific object before the verb, but it is a different construction.', false, false),
('object_o:mr', 'object_o', 'mr', 'ला (people, specific things)', 'ला on people and some definite objects; things usually take nothing.', true, false),
('object_o:en', 'object_o', 'en', '— (after the verb)', 'Position only.', false, false),
('place_de_ni:ja', 'place_de_ni', 'ja', 'で / に', 'で = where an action happens. に = where something is (with いる / ある).', true, false),
('place_de_ni:my', 'place_de_ni', 'my', 'မှာ', 'One particle for both: where something happens and where something is.', true, false),
('place_de_ni:zh', 'place_de_ni', 'zh', '在 … / place + 里 + 有', '在 + place before the verb for actions. ''There is'' uses place + 里 + 有, without 在.', true, false),
('place_de_ni:mr', 'place_de_ni', 'mr', '-त / मध्ये', 'One locative ending for both.', true, false),
('place_de_ni:en', 'place_de_ni', 'en', 'at / in', 'Prepositions, chosen by the place, not by action vs existence.', true, false),
('direction_ni_e:ja', 'direction_ni_e', 'ja', 'に / へ (read え)', 'へ = direction; に = goal or receiver. Different from を.', true, false),
('direction_ni_e:my', 'direction_ni_e', 'my', 'ကို', 'The same ကို as for objects, used for where you go and who receives.', true, false),
('direction_ni_e:zh', 'direction_ni_e', 'zh', '— (去 + place) / 给 (to a person)', 'Place goes straight after 去 with no marker. The receiver uses 给 before the verb.', true, false),
('direction_ni_e:mr', 'direction_ni_e', 'mr', 'ला', 'One ending for the goal, the receiver, and people as objects, like Burmese ကို.', true, false),
('direction_ni_e:en', 'direction_ni_e', 'en', 'to', 'One preposition for place and person.', true, false),
('also_mo:ja', 'also_mo', 'ja', 'も', 'Replaces は / が / を after the noun.', true, false),
('also_mo:my', 'also_mo', 'my', 'လည်း', 'After the noun, in the same place as も.', true, false),
('also_mo:zh', 'also_mo', 'zh', '也 (before the verb) / 都', '也 goes before the verb, not after the noun. ''Both … and …'' moves the nouns first and uses 都.', true, false),
('also_mo:mr', 'also_mo', 'mr', '-ही / पण', '-ही sticks to the noun, exactly where も goes.', true, false),
('also_mo:en', 'also_mo', 'en', 'too / also', 'At the end or before the verb.', true, false),
('from_until:ja', 'from_until', 'ja', 'から … まで', 'After the noun.', true, false),
('from_until:my', 'from_until', 'my', 'ကနေ / မှ … အထိ / ထိ', 'After the noun, same place as Japanese.', true, false),
('from_until:zh', 'from_until', 'zh', '从 … 到 …', 'Before the noun, and the whole phrase goes before the verb.', true, false),
('from_until:mr', 'from_until', 'mr', '-पासून … -पर्यंत', 'After the noun, like Japanese and Burmese.', true, false),
('from_until:en', 'from_until', 'en', 'from … to / until', 'Prepositions before the noun.', true, false),
('possessive_no:ja', 'possessive_no', 'ja', 'の', 'Between owner and thing. Also for kinds: 日本の車.', true, false),
('possessive_no:my', 'possessive_no', 'my', 'ရဲ့ (tone change for ''my, your'')', 'ရဲ့ after the owner. For pronouns the tone changes instead: ကျွန်တော် → ကျွန်တော့်.', true, false),
('possessive_no:zh', 'possessive_no', 'zh', '的', 'Between owner and thing; left out for family and close ties.', true, false),
('possessive_no:mr', 'possessive_no', 'mr', '-चा / -ची / -चे', 'The ending agrees with the gender and number of the thing owned.', true, false),
('possessive_no:en', 'possessive_no', 'en', '''s / of', 'Fixed form.', true, false),
('with_to:ja', 'with_to', 'ja', 'と', '''A と B'' = A and B. ''person と'' = with a person.', true, false),
('with_to:my', 'with_to', 'my', 'နဲ့', 'Same double job as と.', true, false),
('with_to:zh', 'with_to', 'zh', '和 / 跟 (… 一起)', 'Both mean ''and'' and ''with''. ''With'' sits before the verb.', true, false),
('with_to:mr', 'with_to', 'mr', 'आणि / -बरोबर', 'Two different words: आणि for ''and'', -बरोबर (or सोबत) for ''with''.', true, false),
('with_to:en', 'with_to', 'en', 'and / with', 'Two different words.', true, false),
('yes_no_ka:ja', 'yes_no_ka', 'ja', 'か', 'At the very end. In casual speech, rising tone alone.', true, false),
('yes_no_ka:my', 'yes_no_ka', 'my', 'လား', 'Replaces or follows the ending: မယ် → မလား, တယ် → သလား.', true, false),
('yes_no_ka:zh', 'yes_no_ka', 'zh', '吗', 'At the end of a normal statement.', true, false),
('yes_no_ka:mr', 'yes_no_ka', 'mr', 'का', 'At the end (or the start) of a normal statement.', true, false),
('yes_no_ka:en', 'yes_no_ka', 'en', '— (swap verb and subject)', 'No particle; ''You are'' becomes ''Are you''.', false, false),
('wh_question:ja', 'wh_question', 'ja', 'question word + か', 'Same か as yes/no questions.', true, false),
('wh_question:my', 'wh_question', 'my', 'question word + လဲ', 'လဲ, not လား, when there is a question word.', true, false),
('wh_question:zh', 'wh_question', 'zh', 'question word, no 吗', 'The question word alone makes it a question.', true, false),
('wh_question:mr', 'wh_question', 'mr', 'question word, no का', 'Like Chinese: no particle when there is a question word.', true, false),
('wh_question:en', 'wh_question', 'en', 'question word moves to the front', 'Plus do / are before the subject.', true, false),
('tag_ne:ja', 'tag_ne', 'ja', 'ね (agree?) / よ (I tell you)', 'ね checks agreement; よ gives new information.', true, false),
('tag_ne:my', 'tag_ne', 'my', 'နော်', 'At the end: ''right?'', ''OK?''.', true, false),
('tag_ne:zh', 'tag_ne', 'zh', '吧 / 啊', '吧 = ''I suppose, right?''; 啊 softens. Neither is an exact ね.', true, false),
('tag_ne:mr', 'tag_ne', 'mr', 'ना', 'At the end: ''right?'', or ''do…'' in a request.', true, false),
('tag_ne:en', 'tag_ne', 'en', '…, isn''t it? / right?', 'A tag question that copies the verb.', true, false),
('past:ja', 'past', 'ja', 'た / ました', 'Always marked. Also used for ''already done''.', true, false),
('past:my', 'past', 'my', '(ခဲ့) တယ် / ပြီ', 'တယ် = real, not future (past or present). ခဲ့ makes it clearly past. ပြီ = already / now.', true, false),
('past:zh', 'past', 'zh', '了 (completed) / time word', 'No tense. A time word sets the time; 了 marks a finished action.', true, false),
('past:mr', 'past', 'mr', 'past tense (-ला / -ली / -लं)', 'Real past tense; the ending agrees in gender and number.', true, false),
('past:en', 'past', 'en', '-ed / irregular past', 'Real past tense.', true, false),
('progressive:ja', 'progressive', 'ja', 'て + いる', 'Action in progress, or the state after a change (窓が開いている = the window is open).', true, false),
('progressive:my', 'progressive', 'my', 'နေ (doing) / ထား (state)', 'Two forms. နေ for in progress; ထား for a state someone left.', true, false),
('progressive:zh', 'progressive', 'zh', '正在 / 在 (doing) / 着 (state)', '正在 before the verb for in progress; 着 after the verb for a lasting state.', true, false),
('progressive:mr', 'progressive', 'mr', '-त आहे (doing) / adjective (state)', 'Present continuous for in progress; a state is said with an adjective.', true, false),
('progressive:en', 'progressive', 'en', 'be + -ing', 'Only in progress; a state uses an adjective (open).', true, false),
('future:ja', 'future', 'ja', 'non-past (る / ます) / つもり', 'No future tense. The time word does the work; つもり = intend to.', true, false),
('future:my', 'future', 'my', 'မယ်', 'Future ending, replacing တယ်.', true, false),
('future:zh', 'future', 'zh', 'time word / 要 / 打算', 'No tense; 要 = going to, 打算 = plan to.', true, false),
('future:mr', 'future', 'mr', 'future tense (-ईन) / -णार आहे', 'Real future endings; -णार आहे = going to.', true, false),
('future:en', 'future', 'en', 'will / going to', 'Helper verbs.', true, false),
('experience:ja', 'experience', 'ja', 'た + ことがある', 'Past form + ことがある / ことがない.', true, false),
('experience:my', 'experience', 'my', 'ဖူး', 'Right after the verb.', true, false),
('experience:zh', 'experience', 'zh', '过', 'Right after the verb; negative uses 没.', true, false),
('experience:mr', 'experience', 'mr', '— (perfect tense + कधी)', 'No special form. The perfect tense, with कधी / कधीच for ''ever / never''.', false, false),
('experience:en', 'experience', 'en', 'have + past participle', 'Present perfect, often with ''ever / never''.', true, false),
('want_tai:ja', 'want_tai', 'ja', 'verb stem + たい', 'Then behaves like an adjective (たかった, たくない).', true, false),
('want_tai:my', 'want_tai', 'my', 'verb + ချင်', 'Then the normal ending: ချင်တယ်.', true, false),
('want_tai:zh', 'want_tai', 'zh', '想 + verb', 'Before the verb, like English ''want to''.', true, false),
('want_tai:mr', 'want_tai', 'mr', 'मला + verb-ायचं + आहे', 'The person wanting takes ला; the verb becomes -ायचं.', true, false),
('want_tai:en', 'want_tai', 'en', 'want to + verb', 'Before the verb.', true, false),
('ability:ja', 'ability', 'ja', 'potential form / できる', 'One form for skill, possibility and permission.', true, false),
('ability:my', 'ability', 'my', 'တတ် (skill) / နိုင် (able)', 'Pick by meaning.', true, false),
('ability:zh', 'ability', 'zh', '会 (skill) / 能 (able) / 可以 (allowed)', 'Three words, before the verb.', true, false),
('ability:mr', 'ability', 'mr', 'येणे (skill) / शकणे (able)', 'Skill: मला … येतं. Able: … शकतो.', true, false),
('ability:en', 'ability', 'en', 'can', 'One word for all meanings, like Japanese.', true, false),
('because:ja', 'because', 'ja', 'reason + から / ので', 'At the end of the reason clause. ので is softer.', true, false),
('because:my', 'because', 'my', 'reason + လို့ / ကြောင့်', 'At the end of the reason.', true, false),
('because:zh', 'because', 'zh', '因为 … 所以 …', 'At the start of each clause; either can be dropped.', true, false),
('because:mr', 'because', 'mr', 'reason + म्हणून', 'At the end of the reason, like から. (कारण goes before the reason, like ''because''.)', true, false),
('because:en', 'because', 'en', 'because + reason / reason, so …', '''Because'' goes before the reason.', true, false),
('politeness:ja', 'politeness', 'ja', 'ます / です (polite) vs plain', 'The verb ending itself changes with who you talk to.', true, false),
('politeness:my', 'politeness', 'my', 'ပါ', 'ပါ before the ending, or after a command, makes it polite.', true, false),
('politeness:zh', 'politeness', 'zh', '— (polite words: 您, 请)', 'No polite verb form. Use 您 instead of 你, and 请 for requests.', false, false),
('politeness:mr', 'politeness', 'mr', 'तुम्ही / आपण + plural verb', 'Respect comes from the plural ''you'', which changes the verb ending.', true, false),
('politeness:en', 'politeness', 'en', '— (please / could you)', 'No polite grammar; only words and tone.', false, false),
('negation:ja', 'negation', 'ja', 'ない / ません (after the verb)', 'An ending on the verb.', true, false),
('negation:my', 'negation', 'my', 'မ + verb + ဘူး', 'Around the verb. The ending တယ် / မယ် disappears.', true, false),
('negation:zh', 'negation', 'zh', '不 / 没 + verb', 'Before the verb. 不 = don''t / won''t; 没 = didn''t / haven''t.', true, false),
('negation:mr', 'negation', 'mr', 'verb + नाही', 'After the verb, like Japanese.', true, false),
('negation:en', 'negation', 'en', 'do not / not', 'Before the verb, with ''do''.', true, false),
('counters:ja', 'counters', 'ja', 'noun + number + counter', '本 = long things, 枚 = flat things, 匹 = small animals.', true, false),
('counters:my', 'counters', 'my', 'noun + number + counter', 'ချောင်း = long things, ချပ် = flat things, ကောင် = animals.', true, false),
('counters:zh', 'counters', 'zh', 'number + counter + noun', '支 = pens, 张 = flat things, 只 = animals. Counter is required.', true, false),
('counters:mr', 'counters', 'mr', '— (number + noun; जण for people)', 'No counters for things. People can take जण.', false, false),
('counters:en', 'counters', 'en', '— (number + noun)', 'No counters, except phrases like ''two sheets of paper''.', false, false)
