('verb_final:ja:1', 'verb_final:ja', 1, '私はりんごを食べます。', 'わたし わ りんご お たべます', 'I eat an apple.', array['食べます']::text[], 'वाताशि वा रिंगो ओ ताबेमासु', 'null'::jsonb),
('verb_final:ja:2', 'verb_final:ja', 2, '弟が学校へ行った。', 'おとうと が がっこう え いった', 'My younger brother went to school.', array['行った']::text[], 'ओतोतो गा गाक्को ए इत्ता', '{"say":"","sayDev":"","ch":[{"w":"学校","from":"がく + こう","to":"がっこう","rule":"ja_sokuon"},{"w":"行った","from":"いく + た","to":"いった","rule":"ja_te"}]}'::jsonb),
