('modifier_before_noun:my:1', 'modifier_before_noun:my', 1, 'မနေ့က ဝယ်ခဲ့တဲ့ စာအုပ်', null, 'the book I bought yesterday', array['တဲ့']::text[], 'मनेक वैखैतै साओʼ', '{"say":"မနေ့ဂ ဝယ်ဂဲ့ဒဲ့ စာအုပ်","sayDev":"मनेग वैगैदै साओʼ","ch":[{"w":"က","sayW":"ဂ","from":"क","to":"ग","rule":"my_voice"},{"w":"ခဲ့","sayW":"ဂဲ့","from":"खै","to":"गै","rule":"my_voice"},{"w":"တဲ့","sayW":"ဒဲ့","from":"तै","to":"दै","rule":"my_voice"}]}'::jsonb),
('modifier_before_noun:my:2', 'modifier_before_noun:my', 2, 'ဂျပန်စကား ပြောတဲ့ လူ', null, 'a person who speaks Japanese', array['တဲ့']::text[], 'जपंसका प्योतै लू', '{"say":"ဂျပန်ဇဂား ပြောဒဲ့ လူ","sayDev":"जपंजगा प्योदै लू","ch":[{"w":"စ","sayW":"ဇ","from":"स","to":"ज","rule":"my_voice"},{"w":"ကား","sayW":"ဂား","from":"का","to":"गा","rule":"my_voice"},{"w":"တဲ့","sayW":"ဒဲ့","from":"तै","to":"दै","rule":"my_voice"}]}'::jsonb),
