('topic_wa:my:1', 'topic_wa:my', 1, 'ကျွန်တော်ကတော့ လက်ဖက်ရည် သောက်မယ်။', null, 'As for me, I''ll drink tea.', array['ကတော့']::text[], 'च्वंतोकतो लेʼफेʼयी थाउʼमै', '{"say":"ကျွန်တော်ဂဒော့ လက်ဖက်ရည် သောက်မယ်။","sayDev":"च्वंतोगदो लेʼफेʼयी थाउʼमै","ch":[{"w":"က","sayW":"ဂ","from":"क","to":"ग","rule":"my_voice"},{"w":"တော့","sayW":"ဒော့","from":"तो","to":"दो","rule":"my_voice"}]}'::jsonb),
