('object_o:zh:2', 'object_o:zh', 2, '我把书看完了。', 'wǒ bǎ shū kàn wán le', 'I''ve finished reading the book.', array['把']::text[], 'वोˇ बाˇ षु- खान` वान´ ल', '{"say":"wó bǎ shū kàn wán le","sayDev":"वो´ बाˇ षु- खान` वान´ ल","ch":[{"w":"我","from":"wǒ","to":"wó","rule":"zh_t3"}]}'::jsonb),
